#!/usr/bin/env python3
"""Zweiter Patch: Schnee mit Finger-Physik, Rudolph, Schneehaube, Schlitten.
Zuerst advent_patch.py ausführen. Aufruf: python optik_patch.py index.html (legt index.html.bak2 an)"""
import sys,shutil
pfad=sys.argv[1] if len(sys.argv)>1 else 'index.html'
roh=open(pfad,encoding='utf-8',newline='').read()
crlf='\r\n' in roh
src=roh.replace('\r\n','\n')
if 'id="rudolph"' in src: sys.exit('Schon gepatcht (Rudolph vorhanden).')
if 'ADVENT_TESTTAG' not in src: sys.exit('Bitte zuerst advent_patch.py ausführen.')
def rep(a,b):
    global src
    assert src.count(a)==1,'Anker nicht eindeutig gefunden: '+a[:70]
    src=src.replace(a,b)
CSS='body.deko main header{padding-top:36px}\n.karte.haube::before{content:"";position:absolute;left:16px;right:16px;top:0;height:14px;pointer-events:none;filter:drop-shadow(0 1.5px 0 rgba(32,64,96,.14));\nbackground:linear-gradient(#f4f8fc,#f4f8fc) 0 0/100% 4px no-repeat,\nradial-gradient(circle 5px at 11px 4px,#f4f8fc 98%,#0000) 0 0/88px 14px repeat-x,\nradial-gradient(circle 8px at 33px 4px,#f4f8fc 98%,#0000) 0 0/88px 14px repeat-x,\nradial-gradient(circle 7px at 55px 4px,#f4f8fc 98%,#0000) 0 0/88px 14px repeat-x,\nradial-gradient(circle 6px at 77px 4px,#f4f8fc 98%,#0000) 0 0/88px 14px repeat-x}\n#rudolph{position:fixed;left:0;top:0;z-index:6;display:none;padding:8px;cursor:pointer;will-change:transform}\n#rTier{position:relative;display:inline-block;font-size:44px;line-height:1}\n#rNase{position:absolute;left:50%;top:50%;width:26px;height:26px;border-radius:50%;opacity:0;background:radial-gradient(circle,#ff1744,rgba(255,23,68,.4) 60%,transparent 70%)}\n.rf{position:absolute;left:50%;top:50%;margin:-10px;font-size:18px;line-height:1;opacity:0}\n#rBlase{position:absolute;left:50%;bottom:100%;width:max-content;max-width:180px;margin-bottom:-4px;padding:6px 10px;border-radius:12px;background:var(--chip);color:var(--tx);font-size:14px;font-weight:600;line-height:1.3;box-shadow:0 1px 4px rgba(0,0,0,.25);display:none;text-align:left}\n#schlitten{position:fixed;top:calc(180px + env(safe-area-inset-top));left:0;z-index:7;font-size:44px;white-space:nowrap;pointer-events:none;display:none}\n'
JS="/* ---------- Schneefall mit Finger, Rudolph, Schlitten ---------- */\nlet fern=[],finger=null,vorherDruck=null,letzteZeit=0,verstecktAb=null;\nconst gegriffen={i:-1};\nfunction flockenNeu(){\n  fern=Array.from({length:100},()=>flocke(3,6,1,3,.25,.55));\n  flocken=Array.from({length:45},()=>({...flocke(7,13,2,5,.5,.9),ox:0,oy:0,vx:0,vy:0}));\n}\nconst fingerPos=e=>{const p=(e.touches&&e.touches[0])||e;return{x:p.clientX,y:p.clientY}};\nconst opt={passive:true,capture:true};\naddEventListener('touchstart',e=>{finger=fingerPos(e)},opt);\naddEventListener('touchmove',e=>{finger=fingerPos(e)},opt);\naddEventListener('touchend',e=>{finger=e.touches.length?fingerPos(e):null},opt);\naddEventListener('touchcancel',()=>{finger=null},opt);\naddEventListener('mousedown',e=>{finger=fingerPos(e)},opt);\naddEventListener('mousemove',e=>{if(e.buttons)finger=fingerPos(e)},opt);\naddEventListener('mouseup',()=>{finger=null},opt);\nconst basis=(f,t)=>({x:f.x*W+Math.sin((f.ph+f.sw*t)*2*Math.PI)*14,y:((f.v+f.tempo*t)%1)*H});\nfunction physik(t,jetzt){\n  const dt=Math.min(.05,Math.max(.001,(jetzt-letzteZeit)/1000));letzteZeit=jetzt;\n  const d=finger;\n  if(d&&!vorherDruck){\n    let b=-1,ba=44;\n    flocken.forEach((f,i)=>{const p=basis(f,t),a=Math.hypot(p.x+f.ox-d.x,p.y+f.oy-d.y);if(a<ba){ba=a;b=i}});\n    gegriffen.i=b;\n  }\n  if(!d)gegriffen.i=-1;\n  vorherDruck=d;\n  const g=gegriffen.i,reich=g>=0?70:90,gr=3000;\n  flocken.forEach((f,i)=>{\n    const p=basis(f,t);\n    if(i===g&&d){\n      const nx=d.x-p.x,ny=d.y-p.y;\n      f.vx=Math.max(-gr,Math.min(gr,(nx-f.ox)/dt));f.vy=Math.max(-gr,Math.min(gr,(ny-f.oy)/dt));\n      f.ox=nx;f.oy=ny;return;\n    }\n    if(d){\n      const dx=p.x+f.ox-d.x,dy=p.y+f.oy-d.y,a=Math.hypot(dx,dy);\n      if(a<reich&&a>1){const s=1-a/reich;f.vx+=dx/a*s*1600*dt;f.vy+=dy/a*s*1600*dt}\n    }\n    f.ox+=f.vx*dt;f.oy+=f.vy*dt;\n    const br=Math.max(0,1-3*dt);f.vx*=br;f.vy*=br;\n    const zu=Math.max(0,1-.9*dt);f.ox*=zu;f.oy*=zu;\n  });\n}\nfunction zeichneSchnee(t,jetzt){\n  const c=sc.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,W,H);\n  const farbe=getComputedStyle(document.documentElement).getPropertyValue('--flake').trim();\n  physik(t,jetzt||performance.now());\n  for(const f of fern){const b=basis(f,t);kristall(c,b.x,b.y,f.r,f.ph*360+t*f.dr*360,farbe,f.a)}\n  flocken.forEach((f,i)=>{\n    const b=basis(f,t),g=i===gegriffen.i;\n    kristall(c,b.x+f.ox,b.y+f.oy,f.r*(g?1.4:1),f.ph*360+t*f.dr*360,farbe,g?1:f.a);\n  });\n}\n\n/* --- Schlitten bei neuem Eintrag: Karte erscheint, wenn er in der Mitte ist --- */\nfunction schlittenFlug(){\n  const e=$('#schlitten'),t0=performance.now();let mitte=false;e.style.display='block';\n  const f=t=>{\n    const p=Math.min(1,(t-t0)/2000);\n    e.style.transform=`translate(${(innerWidth+140)-(innerWidth+280)*p}px,${Math.sin(p*4*Math.PI)*18}px)`;\n    if(p>=.5&&!mitte){mitte=true;verstecktAb=null;liste()}\n    if(p<1)requestAnimationFrame(f);else{e.style.display='none';verstecktAb=null;liste()}\n  };\n  requestAnimationFrame(f);\n}\n\n/* --- Rudolph --- */\nconst RENTIER_BLICKT_LINKS=true; // false, falls das Rentier rückwärts läuft\nconst NASE_X=-20,NASE_Y=-6;      // Lage der Nase zur Emoji-Mitte, auf dem iPhone ggf. anpassen\nconst SPRUECHE=['Ho ho ho! 🎅','Schon wieder ein Glühwein?','Meine Nase leuchtet nur für dich. 🔴','Frohe Weihnachten! 🎄','Hast du schon bewertet?','🎁 Bald ist Bescherung!'];\nconst rEl=$('#rudolph'),rTier=$('#rTier'),rNase=$('#rNase'),rBlase=$('#rBlase'),rFl=[...document.querySelectorAll('.rf')];\nconst R={gr:1,sp:0,wa:0,sn:0,na:0};\nlet rSicht=false,rRechts=true,rBahn=.7,rPos=0,rPause=false,rTipps=0,rErinnert=false,rSofort=false,rBis=performance.now()+rnd(8000,15000),rLetzt=0;\nconst schlaf=ms=>new Promise(r=>setTimeout(r,ms));\nconst tw=(k,z,ms)=>new Promise(ok=>{const a=R[k],t0=performance.now();const f=t=>{const p=Math.min(1,(t-t0)/ms);R[k]=a+(z-a)*p;if(p<1)requestAnimationFrame(f);else ok()};requestAnimationFrame(f)});\nconst rAktiv=()=>deko()&&!$('#haupt').style.display&&!document.querySelector('dialog[open]')&&$('#gross').style.display!=='flex';\nconst rMitte=()=>(innerWidth+120)*(rRechts?rPos:1-rPos)-120+35;\nconst imBild=rand=>{if(!rSicht)return false;const m=rMitte();return m>=rand&&m<=innerWidth-rand};\nconst adventHinweis=()=>$('#adHinweis').textContent||null;\nconst adventWissen=()=>{const o=adventOffen();return ADV.map((a,i)=>[a,i+1]).filter(([a,t])=>o.has(adventKey(t))&&a[0]!=='Aufgabe').map(([a])=>`${sym(a[0])} ${a[1]}`)};\nrNase.style.marginLeft=(NASE_X-13)+'px';rNase.style.marginTop=(NASE_Y-13)+'px';\nfunction rRender(){\n  const W2=innerWidth,H2=innerHeight,an=rRechts?rPos:1-rPos;\n  const x=(W2+120)*an-120,hup=rPause?0:Math.abs(Math.sin(rPos*60))*12,y=H2*rBahn-hup-R.sp*28;\n  rEl.style.transform=`translate(${x}px,${y}px)`;\n  const sp=(rRechts===RENTIER_BLICKT_LINKS)?-1:1;\n  rTier.style.transform=`scale(${sp*R.gr},${R.gr}) rotate(${R.wa}deg)`;\n  rNase.style.opacity=Math.min(1,Math.max(0,R.na));rNase.style.transform=`scale(${R.na})`;\n  rFl.forEach((e,k)=>{const w=k*Math.PI/4,d=R.sn*90;e.style.opacity=R.sn>0?1-R.sn:0;e.style.transform=`translate(${Math.cos(w)*d}px,${Math.sin(w)*d-R.sn*20}px)`});\n  const m=rMitte(),sh=Math.min(Math.max(m,95),W2-95)-m;\n  rBlase.style.transform=`translateX(calc(-50% + ${sh}px))`;\n}\nasync function reagiere(text){\n  if(rPause)return;\n  rPause=true;rTipps++;navigator.vibrate?.(30);\n  const h=adventHinweis(),w=adventWissen();\n  const t=text||(rTipps%5===0?'🍷 Prost, auf dich!':h&&rTipps%2===1?h:w.length&&Math.random()<.5?w[Math.floor(Math.random()*w.length)]:SPRUECHE[Math.floor(Math.random()*SPRUECHE.length)]);\n  rBlase.textContent=t;rBlase.style.display='block';\n  tw('gr',1.5,250);tw('na',1,300);\n  (async()=>{R.sn=0;await tw('sn',1,1100);R.sn=0})();\n  for(let i=0;i<2;i++){await tw('sp',1,170);await tw('sp',0,170)}\n  await tw('wa',12,120);await tw('wa',-12,160);await tw('wa',0,120);\n  await schlaf(Math.max(600,t.length*45));\n  tw('na',0,250);await tw('gr',1,250);\n  rBlase.style.display='none';rPause=false;\n}\nasync function rentierJubel(){\n  let v=0;\n  while((rPause||!imBild(innerWidth*.3))&&v<200){if(!rSicht)rSofort=true;await schlaf(100);v++}\n  if(!rPause&&imBild(innerWidth*.3))reagiere('Fünf Tassen! 🏆');\n  rSofort=false;\n}\nfunction rTick(ms){\n  requestAnimationFrame(rTick);\n  if(document.hidden){rLetzt=0;return}\n  const dt=rLetzt?Math.min(.1,(ms-rLetzt)/1000):0;rLetzt=ms;\n  if(!rSicht){\n    if(rSofort||ms>=rBis){\n      if(!deko()){rBis=ms+5000;return}\n      rRechts=Math.random()<.5;rBahn=.55+Math.random()*.3;rPos=0;rSicht=true;\n    }else return;\n  }\n  if(!rPause)rPos+=dt/8;\n  if(!rErinnert&&!rPause&&adventHinweis()&&rPos>=.4&&rPos<=.6&&imBild(innerWidth*.3)){rErinnert=true;reagiere(adventHinweis())}\n  rEl.style.display=rAktiv()?'block':'none';\n  rRender();\n  if(rPos>=1){rSicht=false;rEl.style.display='none';rBis=ms+rnd(25000,60000)}\n}\nrEl.addEventListener('click',()=>{if(imBild(45))reagiere()});\nrequestAnimationFrame(rTick);\n"
rep('</style>',CSS+'</style>')
rep('<div id="gross">','<div id="rudolph"><div id="rBlase"></div><div id="rTier"><span>🦌</span><i id="rNase"></i>'+'<b class="rf">❄</b>'*8+'</div></div>\n<div id="schlitten">🎅🛷✨</div>\n<div id="gross">')
# Schnee: alte Zeichenfunktion entfernen, neue Flocken anlegen
a=src.index('function zeichneSchnee(t){');b=src.index('function zeichneLichter')
src=src[:a]+src[b:]
rep('flocken=[...Array.from({length:60},()=>flocke(3,6,1,3,.25,.55)),...Array.from({length:45},()=>flocke(4,11,2,5,.5,.9))];','flockenNeu();')
rep('zeichneSchnee(t);','zeichneSchnee(t,ms);')
rep("sc.style.display=lc.style.display=an?'block':'none';","sc.style.display=lc.style.display=an?'block':'none';document.body.classList.toggle('deko',an);")
# Schneehaube auf den Karten, neue Karte erst bei Schlitten-Mitte zeigen
rep("k.className='karte';","k.className='karte'+(deko()?' haube':'');")
rep('for(const w of sortiert()){','for(const w of sortiert().filter(w=>verstecktAb==null||w.id<=verstecktAb)){')
# Jubel bei 5 Tassen und Schlitten bei neuem Eintrag
rep('async v=>{w.wertung=v;w.geaendert=Date.now();await sichern(w);liste()}','async v=>{const war=w.wertung;w.wertung=v;w.geaendert=Date.now();await sichern(w);liste();if(v>=5&&war<5)rentierJubel()}')
rep('await sichern(w);weine=await alle();ansicht(false);liste();','const jub=w.wertung>=5&&(aktuell?.wertung||0)<5,neuEintrag=!aktuell&&deko();if(neuEintrag){verstecktAb=weine.reduce((m,x)=>Math.max(m,x.id),0);sort=\'neueste\';asc=false}await sichern(w);weine=await alle();ansicht(false);liste();if(neuEintrag)schlittenFlug();if(jub)rentierJubel();')
rep('/* ---------- Start ---------- */',JS+'\n/* ---------- Start ---------- */')
shutil.copyfile(pfad,pfad+'.bak2')
open(pfad,'w',encoding='utf-8',newline='').write(src.replace('\n','\r\n') if crlf else src)
print('Fertig. Sicherung:',pfad+'.bak2')
